import json

payload = '''
{
  "status": "OK",
  "results": [
    { "formatted_address": "Northeastern University, Boston, MA 02115, USA", "lat": 42.3396998, "lng": -71.08975, "place_id": "ChIJ0X6Y1cdw44kRfCQ5p1WHWvA" },
    { "formatted_address": "Bradley University, Peoria, IL 61625, USA", "lat": 40.6963857, "lng": -89.6160811, "place_id": "ChIJN1t_tDeuEmsRUsoyG83frY4" },
    { "formatted_address": "Monash University, Clayton VIC 3800, Australia", "lat": -37.9152113, "lng": 145.134682, "place_id": "ChIJrTLrKyuEj4ARi29s3WvMx0Q" },
    { "formatted_address": "Kokshetau, Kazakhstan", "lat": 53.2833333, "lng": 69.3833333, "place_id": "ChIJ2c1nZAHDvJURf8Qz8x0X0vQ" }
  ]
}'''

js = json.loads(payload)

place = None
if js['status'] == 'OK':
    place = js

if place is None:
    print('status: error')
else:
    print('places: %d' % len(place['results']))
    for r in place['results']:
        name = r['formatted_address'].split(',')[0]
        print('%s -> %s, %s' % (name, r['lat'], r['lng']))
    first = place['results'][0]
    print('first place id: %s' % first['place_id'])

links = [
    ('page1', 'page2'), ('page1', 'page3'), ('page2', 'page3'),
    ('page3', 'page1'), ('page3', 'page2'), ('page4', 'page3'),
]
counts = dict()
for a, b in links:
    counts[a] = counts.get(a, 0) + 1
    counts[b] = counts.get(b, 0) + 1

for name in sorted(counts):
    print('node: %s %d' % (name, counts[name]))

best = None
for name in counts:
    if best is None or counts[name] > counts[best]:
        best = name
print('hub: %s %d' % (best, counts[best]))

counts = {'gmail.com': 4, 'umich.edu': 2, 'uct.ac.za': 1}

def draw_bars(pairs, width):
    biggest = 0
    for name, value in pairs:
        if value > biggest:
            biggest = value
    for name, value in pairs:
        ticks = int(width * value / biggest)
        print('%s | %s %d' % (name, '#' * ticks, value))

ranked = []
for name, value in counts.items():
    ranked.append((value, name))
ranked.sort(reverse=True)
ordered = []
for value, name in ranked:
    ordered.append((name, value))
draw_bars(ordered, 8)
